# Runtime reflection includes methods generated by the native extension and wrappers.
# It loads the SDK but creates no resources and performs no provider operations.
require 'json'
require 'microsandbox'
rows = []
visited = {}
walk = lambda do |owner, prefix|
  return if visited[owner.object_id]
  visited[owner.object_id] = true
  owner.singleton_methods(false).sort.each { |name| rows << {symbol: "#{prefix}.#{name}", kind: 'callable'} }
  owner.instance_methods(false).sort.each { |name| rows << {symbol: "#{prefix}##{name}", kind: 'callable'} }
  owner.constants(false).sort.each do |name|
    value = owner.const_get(name, false)
    next unless value.is_a?(Module)
    rows << {symbol: "#{prefix}::#{name}", kind: 'type'}
    walk.call(value, "#{prefix}::#{name}")
  end
end
walk.call(Microsandbox, 'Microsandbox')
puts JSON.generate(rows)
